/* DWARF original prototype: void SaveSingleItem(ITEM_MANAGER * this, LPITEM item) */

void __thiscall ITEM_MANAGER::SaveSingleItem(ITEM_MANAGER *this,LPITEM item)

{
  byte bVar1;
  char *pcVar2;
  DWORD dwOwnerID;
  DWORD dwID;
  TPlayerItem t;
  
  if (item->m_pOwner == (CHARACTER *)0x0) {
    dwID = item->m_dwID;
    dwOwnerID = item->m_dwLastOwnerPID;
    CLIENT_DESC::DBPacketHeader(db_clientdesc,'\x1f',0,8);
    CLIENT_DESC::Packet(db_clientdesc,&dwID,4);
    CLIENT_DESC::Packet(db_clientdesc,&dwOwnerID,4);
    sys_log(0,"ITEM_DELETE %s:%lu",
            (uint)item->m_pProto->szLocaleName & (item->m_pProto == (TItemTable *)0x0) - 1,dwID);
  }
  else {
    bVar1 = item->m_bWindow;
    pcVar2 = CHARACTER::GetName(item->m_pOwner);
    sys_log(0,"ITEM_SAVE %s:%d in %s window %d",
            (uint)item->m_pProto->szLocaleName & (item->m_pProto == (TItemTable *)0x0) - 1,
            item->m_dwID,pcVar2,(uint)bVar1);
    t.id = item->m_dwID;
    t.window = item->m_bWindow;
    if (t.window == '\x02') {
      t.pos = item->m_bCell - 0x5a;
    }
    else {
      t.pos = (WORD)item->m_bCell;
    }
    t.vnum = 0;
    t.count = item->m_dwCount;
    if (item->m_pProto != (TItemTable *)0x0) {
      t.vnum = item->m_pProto->dwVnum;
    }
    if ((byte)(t.window - 3) < 2) {
      t.owner = (((item->m_pOwner->super_CEntity).m_lpDesc)->m_accountTable).id;
    }
    else {
      t.owner = item->m_pOwner->m_dwPlayerID;
    }
    (*thecore_memcpy)(t.alSockets,item->m_alSockets,0xc);
    (*thecore_memcpy)(t.aAttr,item->m_aAttr,0x15);
    CLIENT_DESC::DBPacketHeader(db_clientdesc,'\x1e',0,0x34);
    CLIENT_DESC::Packet(db_clientdesc,&t,0x34);
  }
  return;
}
